Plain least squares gives 30 non-zero weights, but the true system has only 7 terms. The two methods differ in how they decide which weights should be zero.

Method 1: SINDy
SINDy (sparse identification of nonlinear dynamics; Brunton, Proctor and Kutz 2016) is built on the assumption that most weights in \(\Xi\) are exactly zero. It estimates \(\Xi\) with sequentially thresholded least squares:

Fit all the terms by least squares.
Set every weight with an absolute value below a threshold \(\lambda\) to zero.
Refit with the terms that are left, and repeat until no weight is below \(\lambda\).

As in the talk, the derivatives come from a Savitzky-Golay filter (Savitzky and Golay 1964), and \(\lambda = 0.1\) as in her code.


viewof sindyLambda = {
  // the slider steps through round values of λ, from 0.001 to 20
  const LAMS = [0.001, 0.002, 0.005, 0.01, 0.02, 0.05, 0.1, 0.2, 0.5, 1, 2, 5, 10, 20];
  let lambda = 0.1, width = 0, render = () =&gt; {};
  // one step per pass of least squares, equation by equation, as in the slides
  let seq = [], finals = [];
  function build() {
    finals = lib.sys.eqs.map((q) =&gt; stlsq(lib.sys.G, q.b, q.yy, lambda));
    seq = [];
    finals.forEach((r, e) =&gt; r.history.forEach((h, p) =&gt; seq.push({ e, p, n: r.history.length, h, prev: p &gt; 0 ? r.history[p - 1] : null })));
  }
  build();
  const card = makeCard(
    "Keep only the large weights",
    "Each step is one pass of least squares. A weight smaller than λ is outlined, and the next pass sets it to 0."
  );
  const { root, toolbar, body } = card;
  root.value = lambda;
  eyebrow(card, "SINDy").set(2, "fit the weights");
  const st = stepper({
    count: () =&gt; seq.length,
    go: (k, animate) =&gt; render(k, animate),
    label: (k) =&gt; `${EQS[seq[k].e]}, pass ${seq[k].p + 1} of ${seq[k].n}`,
    root, swipe: body
  });
  const slider = html`&lt;input type="range" class="viz-range" min="0" max="${LAMS.length - 1}" step="1" aria-label="Threshold λ"&gt;`;
  slider.value = LAMS.indexOf(lambda);
  slider.setAttribute("aria-valuetext", `λ = ${fmtLambda(lambda)}`);
  const lamOut = html`&lt;span class="viz-readout"&gt;&lt;/span&gt;`;
  slider.addEventListener("input", () =&gt; {
    const l = LAMS[+slider.value];
    if (l === lambda) return;
    lambda = l;
    slider.setAttribute("aria-valuetext", `λ = ${fmtLambda(lambda)}`);
    build();
    // show the end result for the new λ; Back walks through its passes
    st.to(seq.length - 1, false);
  });
  // the simulation figure below follows λ when the slider is let go, not on every move
  slider.addEventListener("change", () =&gt; {
    if (root.value === lambda) return;
    root.value = lambda;
    root.dispatchEvent(new Event("input", { bubbles: true }));
  });
  toolbar.append(st.node, st.counter, html`&lt;div class="viz-field"&gt;&lt;span class="viz-field-label"&gt;Threshold λ&lt;/span&gt;${slider}${lamOut}&lt;/div&gt;`);
  function verdict() {
    const nTerms = d3.sum(finals, (r) =&gt; r.active.length);
    if (finals.every((r, j) =&gt; sameTerms(r.coef, lib.truth[j]))) return `✓ ${nTerms} terms, exactly the true ones.`;
    const lost = finals.some((r, j) =&gt; Array.from(lib.truth[j]).some((c, i) =&gt; c !== 0 && r.coef[i] === 0));
    return lost ? `✗ ${nTerms} terms. True terms are lost, so λ is too large.` : `✗ ${nTerms} terms. Extra terms stay, so λ is too small.`;
  }
  function draw() {
    const { chart, side, cw } = split(body, width);
    const rows = termRows(cw);
    chart.append(rows.node, html`&lt;div class="viz-note"&gt;The dots are Ξ, one column per equation: a coloured dot is a weight that is kept, a small grey dot is a weight set to 0.&lt;/div&gt;`);
    const explain = html`&lt;div class="viz-explain" aria-live="polite"&gt;&lt;/div&gt;`;
    const found = html`&lt;div&gt;&lt;/div&gt;`;
    const status = html`&lt;div class="viz-note" style="color:var(--viz-ink);min-height:1.5em"&gt;&lt;/div&gt;`;
    side.append(explain, html`&lt;div class="viz-side-title"&gt;Equations found with λ = &lt;span&gt;&lt;/span&gt;&lt;/div&gt;`, found, status);
    const lamTitle = side.querySelector(".viz-side-title span");
    render = (pos, animate) =&gt; {
      const s = seq[pos], h = s.h, q = EQS[s.e], nA = h.active.length, last = s.p === s.n - 1;
      const active = new Set(h.active);
      lamOut.textContent = lamTitle.textContent = fmtLambda(lambda);
      // Ξ: the equations done so far as found, this one as in this pass, the others as least squares left them
      const xi = [0, 1, 2].map((j) =&gt; lib.labels.map((_, i) =&gt; (j &lt; s.e ? finals[j].coef[i] !== 0 : j &gt; s.e ? true : active.has(i)) ? "on" : "off"));
      const eq = lib.sys.eqs[s.e];
      rows.set({
        e: s.e, mode: "fit", coef: h.coef, xi,
        off: d3.range(lib.labels.length).filter((i) =&gt; !active.has(i)),
        below: h.below,
        err: Math.sqrt(rss(lib.sys.G, eq.b, eq.yy, h.coef) / eq.yy)
      }, animate);
      // what this pass does, in words
      const names = (ix) =&gt; ix.map((i) =&gt; termName(i)).join(", ");
      let t;
      if (nA === 0) {
        t = `&lt;b&gt;${q}, pass ${s.p + 1}.&lt;/b&gt; Every weight fell below λ, so no term is left.`;
      } else {
        t = s.p === 0
          ? `&lt;b&gt;${q}, pass 1.&lt;/b&gt; Least squares with all ${nA} terms.`
          : `&lt;b&gt;${q}, pass ${s.p + 1}.&lt;/b&gt; The outlined weights are now 0. Least squares again with the ${nA} ${nA === 1 ? "term" : "terms"} left.`;
        const fell = s.prev ? h.below.filter((i) =&gt; Math.abs(s.prev.coef[i]) &gt;= lambda) : [];
        if (fell.length) t += ` Refitting changes the weights: ${termName(fell[0])} is now ${fmtW(h.coef[fell[0]])}.`;
        t += h.below.length
          ? ` ${h.below.length === 1 ? "One weight is" : `${h.below.length} weights are`} smaller than λ: ${names(h.below)}.`
          : ` No weight is smaller than λ, so ${q} is done.`;
      }
      explain.innerHTML = t;
      const done = (j) =&gt; j &lt; s.e || (j === s.e && last);
      found.innerHTML = "";
      EQS.forEach((_, j) =&gt; found.append(eqLine(j, done(j) ? finals[j].coef : null, { fixed: 2, cut: 0.005 })));
      status.textContent = pos === seq.length - 1 ? verdict() : "";
    };
  }
  watchWidth(root, (w) =&gt; { width = w; draw(); st.to(st.k, false); }, invalidation);
  return root;
}







