    for (let i = 1; i &lt; pts.length; i++) cum[i] = cum[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]);
    const total = cum[pts.length - 1] + 10;
    sel.attr("d", d3.line()(pts));
    return (k) =&gt; sel.attr("stroke-dasharray", `${cum[Math.max(0, Math.min(pts.length - 1, k))]} ${total}`);
