  const plural = (k) =&gt; `${k} ${k === 1 ? "term" : "terms"}`;
  const st = stepper({
    count: () =&gt; L().length,
    go: (k, animate) =&gt; render(k, animate),
    label: (k) =&gt; `model with ${plural(L()[k].active.length)}`,
    root, swipe: body
  });
